(x, y, t) => {
  const cx = 240, cy = 120;
  const warp1x = Math.sin(x*0.015+t*0.2)*20 + Math.cos(y*0.012-t*0.15)*15;
  const warp1y = Math.cos(y*0.015+t*0.18)*20 + Math.sin(x*0.013+t*0.22)*15;
  const warp2x = Math.sin((x+y)*0.01+t*0.12)*12 + Math.cos((x-y)*0.015-t*0.1)*10;
  const warp2y = Math.cos((x-y)*0.01-t*0.14)*12 + Math.sin((x+y)*0.013+t*0.16)*10;
  const sx = x + warp1x + warp2x, sy = y + warp1y + warp2y;
  const src = [
    [160+Math.sin(t*0.5)*110, 70+Math.cos(t*0.35)*55, 0.075, 2.1, 1.0],
    [320+Math.cos(t*0.45)*110, 170+Math.sin(t*0.6)*55, 0.09, 1.8, 0.8],
    [240+Math.sin(t*0.28+2)*150, 110+Math.cos(t*0.42+1)*95, 0.055, 2.4, 1.2],
    [100+Math.cos(t*0.7+1)*90, 190+Math.sin(t*0.55+3)*65, 0.11, 1.6, 0.9],
    [380+Math.sin(t*0.38+4)*100, 55+Math.cos(t*0.8+2)*75, 0.065, 2.7, 1.1],
    [240+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.48)*85, 0.085, 2.0, 0.7],
    [60+Math.sin(t*0.6+3)*70, 50+Math.cos(t*0.5+4)*50, 0.1, 2.3, 0.85],
    [420+Math.cos(t*0.4+1)*60, 200+Math.sin(t*0.65+2)*55, 0.07, 1.9, 1.05]
  ];
  let aS=0, iS=0, harm=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const a=Math.sin(d*f-t*sp), b=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS+=a*w; iS+=b*w; harm+=Math.cos(d*f*0.5-t*sp*0.8+2.0)*w;
  }
  const n=src.reduce((s,v)=>s+v[4],0);
  const act=aS/n, inh=iS/n, hrm=harm/n;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1=Math.sin(dist*0.045-ang*3.5-t*1.6);
  const sp2=Math.sin(dist*0.035+ang*4.5-t*1.1);
  const sp3=Math.sin(dist*0.06-ang*2-t*2.2)*0.5;
  const spiral=(sp1+sp2+sp3)*0.35;
  const bg1=Math.sin(sx*0.035+sy*0.022+t*0.7);
  const bg2=Math.sin(sx*0.028-sy*0.038+t*1.0);
  const bg3=Math.sin((sx+sy)*0.11+t*2.8)*0.25;
  const bg4=Math.sin((sx-sy)*0.09-t*2.3)*0.25;
  const bg5=Math.sin(sx*0.06+sy*0.08-t*1.5)*0.15;
  const bg=(bg1+bg2)/2+bg3+bg4+bg5;
  const cellA=Math.sin(sx*0.14)*Math.sin(sy*0.14);
  const cellB=Math.sin((sx+sy)*0.09+t*0.8)*0.6;
  const cellC=Math.sin((sx*1.5-sy*0.7)*0.07-t*0.5)*0.3;
  const cell=Math.tanh((cellA+cellB+cellC)*1.3)*0.3;
  const ridge=Math.abs(Math.sin(dist*0.08+ang*2-t*0.9))*0.2;
  const reaction=Math.tanh((act-inh*0.65+bg*0.28+spiral+cell*0.5+ridge+hrm*0.15)*2.0);
  const micro=Math.sin(sx*0.3+t*3)*Math.sin(sy*0.35-t*2.5)*0.08*reaction;
  const blend=reaction*0.7+cell*0.2+micro;
  const v=blend*0.5+0.5;
  const pal=[
    [5,12,52],[12,45,95],[18,95,125],[25,155,145],
    [180,200,75],[220,170,55],[195,95,65],[145,45,75],
    [85,22,60],[35,12,55],[5,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.65?1.18:Math.abs(reaction)>0.4?1.06:1.0;
  const depth=1.0+Math.sin(dist*0.02-t*0.3)*0.08;
  const m=depth*edge*lum;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*m)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*m)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*m)|0
  ];
}
